+    } else {
+        return Promise.resolve(1)
+    }
+}
+let l1  = (a: boolean) => {
+    if (a) {
+        return 1
+    } else {
+        return Promise.resolve(1)
+    }
+}
+
+let al2  = async (a: boolean) => {
+    if (a) {
+        return 1
+    } else {
+        return Promise.resolve('s')
+    }
+}
+let l2  = (a: boolean) => {
+    if (a) {
+        return 1
+    } else {
+        return Promise.resolve('s')
+    }
+}
+
+let al3 = async (a: boolean) => {
+    if (a) {
+        return Promise.resolve('s')
+    } else {
+        return 1
+    }
+}
+// Previously resulted in crash
+let l3 = (a: boolean) => {
+    if (a) {
+        return Promise.resolve('s')
+    } else {
+        return 1
+    }
+}
+
+// issue #33499 (ets2panda/checker/ETSAnalyzer.cpp:5129 -- CheckReturnStatementArgumentType)
+async function apair() : Promise<[number, string]> {
+    return [1.0, 'hello']
+}
+
+async function main() {
+    arktest.assertTrue(al1(true) instanceof Promise);
+    arktest.assertEQ(await al1(true), 1);
+    arktest.assertTrue(al1(false) instanceof Promise);
